class GamepadManager {
    getGamepad() {
        const gamepads = navigator.getGamepads();
        return gamepads[0] || null;
    }

    isButtonPressed(index) {
        const gp = this.getGamepad();
        return gp?.buttons[index]?.pressed || false;
    }

    getAxis(index) {
        const gp = this.getGamepad();
        return gp?.axes[index] || 0;
